def main():
    import sys
    import heapq

    def dijkstra(n, edges, start):
        dist = [float('inf')] * (n + 1)
        dist[start] = 0
        pq = [(0, start)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[u]:
                continue
            for v, w in edges[u]:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    heapq.heappush(pq, (dist[v], v))
        return dist

    def find_good_edges(n, m, k, edges):
        # Step 1: Calculate shortest paths from vertex 1 to all other vertices
        dist = dijkstra(n, edges, 1)

        # Step 2: Create a list of edges sorted by their weights
        edge_list = []
        for i in range(1, n + 1):
            for j, w in edges[i]:
                if i < j:
                    edge_list.append((w, i, j))
        edge_list.sort()

        # Step 3: Use a union-find structure to keep track of connected components
        parent = list(range(n + 1))
        rank = [0] * (n + 1)

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                if rank[rootX] > rank[rootY]:
                    parent[rootY] = rootX
                elif rank[rootX] < rank[rootY]:
                    parent[rootX] = rootY
                else:
                    parent[rootY] = rootX
                    rank[rootX] += 1

        # Step 4: Add edges back to the graph in increasing order of weight
        # and check if adding the edge maintains the shortest path
        good_edges = []
        for w, u, v in edge_list:
            if len(good_edges) == k:
                break
            if dist[u] + w == dist[v] or dist[v] + w == dist[u]:
                union(u, v)
                good_edges.append((u, v))

        # Step 5: Check which vertices are still reachable with the original shortest path
        good_vertices = set()
        for u in range(1, n + 1):
            if find(u) == find(1):
                good_vertices.add(u)

        # Step 6: Output the result
        print(len(good_edges))
        if good_edges:
            edge_indices = []
            for i in range(m):
                u, v, _ = edges[1][i]
                if (u, v) in good_edges or (v, u) in good_edges:
                    edge_indices.append(i + 1)
            print(" ".join(map(str, edge_indices)))
        else:
            print("")

